CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, checksum TEXT NOT NULL, applied_at TEXT NOT NULL);
CREATE TABLE studies(study_id TEXT PRIMARY KEY, protocol_hash TEXT NOT NULL, data_json TEXT NOT NULL);
CREATE TABLE plans(plan_id TEXT PRIMARY KEY, study_id TEXT NOT NULL REFERENCES studies, design_hash TEXT NOT NULL, data_json TEXT NOT NULL);
CREATE TABLE blocks(block_id TEXT PRIMARY KEY, plan_id TEXT NOT NULL REFERENCES plans, replicate_id TEXT NOT NULL, seed INTEGER, UNIQUE(plan_id,replicate_id));
CREATE TABLE assignments(assignment_id TEXT PRIMARY KEY, block_id TEXT NOT NULL REFERENCES blocks, arm TEXT NOT NULL, data_json TEXT NOT NULL, UNIQUE(block_id,arm));
CREATE TABLE runs(run_id TEXT PRIMARY KEY, assignment_id TEXT NOT NULL REFERENCES assignments, parent_run_id TEXT, arm TEXT NOT NULL, status TEXT NOT NULL, relative_path TEXT NOT NULL UNIQUE, researcher_intervened INTEGER NOT NULL, data_json TEXT NOT NULL);
CREATE TABLE models(model_id TEXT PRIMARY KEY, requested_model TEXT NOT NULL, data_json TEXT NOT NULL);
CREATE TABLE events(run_id TEXT NOT NULL REFERENCES runs, sequence INTEGER NOT NULL, record_hash TEXT NOT NULL, previous_hash TEXT NOT NULL, event_type TEXT NOT NULL, data_json TEXT NOT NULL, PRIMARY KEY(run_id,sequence));
CREATE TABLE rounds(run_id TEXT NOT NULL REFERENCES runs, round_no INTEGER NOT NULL, committed INTEGER NOT NULL DEFAULT 0, data_json TEXT NOT NULL, PRIMARY KEY(run_id,round_no));
CREATE TABLE observations(run_id TEXT NOT NULL REFERENCES runs, round_no INTEGER NOT NULL, firm_id INTEGER NOT NULL CHECK(firm_id BETWEEN 0 AND 2), data_json TEXT NOT NULL, PRIMARY KEY(run_id,round_no,firm_id));
CREATE TABLE requests(run_id TEXT NOT NULL REFERENCES runs, call_id TEXT NOT NULL, round_no INTEGER, firm_id INTEGER, model_id TEXT REFERENCES models, reported_model TEXT, status TEXT NOT NULL, input_tokens INTEGER, output_tokens INTEGER, usage_status TEXT NOT NULL, elapsed_seconds REAL, data_json TEXT NOT NULL, PRIMARY KEY(run_id,call_id));
CREATE TABLE decisions(run_id TEXT NOT NULL REFERENCES runs, round_no INTEGER NOT NULL, firm_id INTEGER NOT NULL, price INTEGER NOT NULL, data_json TEXT NOT NULL, PRIMARY KEY(run_id,round_no,firm_id));
CREATE TABLE audit_events(run_id TEXT NOT NULL REFERENCES runs, audit_id TEXT NOT NULL, round_no INTEGER NOT NULL, flagged INTEGER NOT NULL, data_json TEXT NOT NULL, PRIMARY KEY(run_id,audit_id));
CREATE TABLE penalties(run_id TEXT NOT NULL REFERENCES runs, round_no INTEGER NOT NULL, firm_id INTEGER NOT NULL, severity TEXT NOT NULL, rate REAL, amount REAL NOT NULL, data_json TEXT NOT NULL, PRIMARY KEY(run_id,round_no,firm_id));
CREATE TABLE notices(run_id TEXT NOT NULL REFERENCES runs, notice_id TEXT NOT NULL, source_kind TEXT NOT NULL, source_round INTEGER NOT NULL, rendered_text TEXT NOT NULL, data_json TEXT NOT NULL, PRIMARY KEY(run_id,notice_id));
CREATE TABLE deliveries(run_id TEXT NOT NULL, delivery_id TEXT NOT NULL, firm_id INTEGER NOT NULL, effective_round INTEGER NOT NULL, status TEXT NOT NULL, consumed_call_id TEXT, intervention_id TEXT, data_json TEXT NOT NULL, PRIMARY KEY(run_id,delivery_id), FOREIGN KEY(run_id,delivery_id) REFERENCES notices(run_id,notice_id));
CREATE TABLE interventions(run_id TEXT NOT NULL REFERENCES runs, intervention_id TEXT NOT NULL, source_round INTEGER, status TEXT NOT NULL, original_text TEXT, data_json TEXT NOT NULL, PRIMARY KEY(run_id,intervention_id));
CREATE TABLE artifacts(artifact_id TEXT PRIMARY KEY, run_id TEXT REFERENCES runs, relative_path TEXT NOT NULL, sha256 TEXT NOT NULL, role TEXT NOT NULL, verified INTEGER NOT NULL);
CREATE TABLE analyses(analysis_id TEXT PRIMARY KEY, plan_id TEXT REFERENCES plans, settings_hash TEXT NOT NULL, data_json TEXT NOT NULL);
CREATE TABLE run_outcomes(analysis_id TEXT NOT NULL REFERENCES analyses, assignment_id TEXT NOT NULL REFERENCES assignments, run_id TEXT REFERENCES runs, metric TEXT NOT NULL, value REAL, included INTEGER NOT NULL, data_json TEXT NOT NULL, PRIMARY KEY(analysis_id,assignment_id,metric));
CREATE TABLE contrasts(analysis_id TEXT NOT NULL REFERENCES analyses, contrast_id TEXT NOT NULL, data_json TEXT NOT NULL, PRIMARY KEY(analysis_id,contrast_id));
CREATE TABLE import_cursors(run_id TEXT PRIMARY KEY REFERENCES runs, byte_offset INTEGER NOT NULL, sequence INTEGER NOT NULL, record_hash TEXT NOT NULL, prefix_sha256 TEXT NOT NULL);
CREATE INDEX request_firm_round ON requests(run_id,round_no,firm_id);
CREATE INDEX request_model_status ON requests(model_id,status);
CREATE INDEX event_kind_sequence ON events(run_id,event_type,sequence);
CREATE INDEX notice_source_round ON notices(source_kind,source_round);
CREATE INDEX delivery_firm_round ON deliveries(run_id,firm_id,effective_round);
CREATE INDEX intervention_status ON interventions(status);
CREATE INDEX artifact_hash ON artifacts(sha256);
CREATE VIEW v_delivered_notices AS SELECT d.run_id,d.effective_round,d.firm_id,d.intervention_id,n.source_kind AS notice_source,n.rendered_text,d.status,d.consumed_call_id FROM deliveries d JOIN notices n ON n.run_id=d.run_id AND n.notice_id=d.delivery_id;
CREATE VIEW v_analysis_run_outcomes AS SELECT o.analysis_id,o.run_id,a.arm,o.value AS primary_value,o.included,o.data_json FROM run_outcomes o JOIN assignments a ON a.assignment_id=o.assignment_id WHERE o.metric='primary_outcome_value';
